tt=t;
sv=e;
if isempty(tt) | isempty(sv)
	% probably during the load process when under a masked block.
	tt=0;
	sv=1;
end
%
if length(sv) ~= length(tt),
   Erreur.message = 'The vectors specifying the time and amplitude pairs must have the same length.';
   Erreur.identifier = 'SpecializedPowerSystems:TimerBlock:ParameterError';
   powericon('psberror',Erreur.message,Erreur.identifier,'NoUiwait');
end
if tt(1)~=0,
   tt=[0 tt];
   sv=[~sv(1) sv];
end
n=length(tt);
vec_dt=[tt,0]-[0,tt] ;
vec_dt=vec_dt(2:n);
if any(vec_dt<=0)
   Erreur.message = 'All transition times must be in increasing order.';
   Erreur.identifier = 'SimscapePowerSystemsST:TimerBlock:ParameterError';
   powericon('psberror',Erreur.message,Erreur.identifier,'NoUiwait');
end
tv=[-1,tt(1),reshape(repmat(reshape(tt(2:end),1,length(tt)-1),2,1),1,2*length(tt)-2),tt(end)+1];
%sv=(sv(:)'~=0);
opv=[sv(1),reshape(repmat(sv(1:end-1),2,1),1,2*length(sv)-2),sv(end),sv(end)];

power_initmask();

tt=t;
sv=e;
if isempty(tt) | isempty(sv)
	% probably during the load process when under a masked block.
	tt=0;
	sv=1;
end
%
if length(sv) ~= length(tt),
   Erreur.message = 'The vectors specifying the time and amplitude pairs must have the same length.';
   Erreur.identifier = 'SpecializedPowerSystems:TimerBlock:ParameterError';
   powericon('psberror',Erreur.message,Erreur.identifier,'NoUiwait');
end
if tt(1)~=0,
   tt=[0 tt];
   sv=[~sv(1) sv];
end
n=length(tt);
vec_dt=[tt,0]-[0,tt] ;
vec_dt=vec_dt(2:n);
if any(vec_dt<=0)
   Erreur.message = 'All transition times must be in increasing order.';
   Erreur.identifier = 'SimscapePowerSystemsST:TimerBlock:ParameterError';
   powericon('psberror',Erreur.message,Erreur.identifier,'NoUiwait');
end
tv=[-1,tt(1),reshape(repmat(reshape(tt(2:end),1,length(tt)-1),2,1),1,2*length(tt)-2),tt(end)+1];
%sv=(sv(:)'~=0);
opv=[sv(1),reshape(repmat(sv(1:end-1),2,1),1,2*length(sv)-2),sv(end),sv(end)];

power_initmask();

switch FilterType
case 1, % Lowpass
    X=[0 1 2 3 4];
    Y=[-2 -2 -3 -4 -4];
    numc=1;
    denc=[Tc 1];
case 2,   % Highpass
    X=[0 1 2 3 4];
    Y=[-4 -4 -3 -2 -2];
    numc=[1 0];
    denc=[1 1/Tc];
end
%
[Ac,Bc,Cc,Dc]=tf2ss(numc,denc);
%
%  Conversion to discrete transfer function
nstates = size(Ac,1);
if Ts<=0
    Erreur.message = 'The Sample time parameter must be greater than zero. Note that specifying inherited sample time (-1) does not work for this block';
    Erreur.identifier = 'SpecializedPowerSystems:Discrete1stOrderFilterBlock:ParameterError';
    powericon('psberror',Erreur.message,Erreur.identifier,'NoUiwait');
end
invexp = inv(eye(nstates) - (Ts/2)*Ac);
Ad = invexp*(eye(nstates) + (Ts/2)*Ac);
Bd = invexp*Bc;
Cd = Cc*invexp*Ts;
Dd = Cc*invexp*Bc*(Ts/2) + Dc;
%
if Initialize==1  % Compute initial conditions on states
    u1=Vac_Init(1)*exp(j*Vac_Init(2)*pi/180);
    u2=Vdc_Init*exp(j*90*pi/180);
    u=u1+u2;
    u0=imag(u); % input at  t=0;
    I=eye(size(Ac));
    sI1=I*j*(2*pi*Vac_Init(3));
    sI2=I*j*0;
    x=inv(sI1-Ac)*Bc*u1 + inv(sI2-Ac)*Bc*u2;
    x0c=imag(x);
    x0d=(I-Ac*Ts/2)*x0c/Ts - Bc/2*u0;
else
    x0d=0;
end

%
if PlotResponse==1 % Plot frequency and step response
t=[0:Tc/1000:7*Tc];
f=param1(1):param1(3):param1(2);
w=2*pi*f;
switch FilterType
	case 1, % Lowpass
		Ystep=1 - exp(-t/Tc);
		RepFreq=1./(1+Tc*j.*w);
	case 2,   % Highpass
		Ystep=exp(-t/Tc);
		RepFreq=1./(1 + (1./(Tc*j.*w)));
end
%
Mag=abs(RepFreq);
Pha=angle(RepFreq)*180/pi;
%
figure(1)
subplot(2,1,1)
plot(f,Mag)
grid
title('Bode Diagram')
ylabel('Magnitude')
subplot(2,1,2)
plot(f,Pha)
ylabel('Phase (deg)')
xlabel('Frequency (Hz)')
grid
figure(2)
plot(t,Ystep)
grid
ylabel('Amplitude')
xlabel('Time (s)')
title('Step Response')
end
power_initmask();

powericon('psbcallbacks',gcb,'Discrete 3-phase PWM Generator');
if ModulatorType==1
    nPulses=6;
    SelectorElements=[1:1:12];
else
    nPulses=12;
 SelectorElements=[1:1:24];
end
if (ModulatingSignals==1 & ModulatorMode==2),
      CmdModulatingSignals=2;
else
      CmdModulatingSignals=1;
end
power_initmask();

tt=t;
sv=e;
if isempty(tt) | isempty(sv)
	% probably during the load process when under a masked block.
	tt=0;
	sv=1;
end
