end
tv=[-1,tt(1),reshape(repmat(reshape(tt(2:end),1,length(tt)-1),2,1),1,2*length(tt)-2),tt(end)+1];
%sv=(sv(:)'~=0);
opv=[sv(1),reshape(repmat(sv(1:end-1),2,1),1,2*length(sv)-2),sv(end),sv(end)];

power_initmask();

switch FilterType
case 1, % Lowpass
    X=[0 1 2 3 4];
    Y=[-2 -2 -3 -4 -4];
    numc=1;
    denc=[Tc 1];
case 2,   % Highpass
    X=[0 1 2 3 4];
    Y=[-4 -4 -3 -2 -2];
    numc=[1 0];
    denc=[1 1/Tc];
end
%
[Ac,Bc,Cc,Dc]=tf2ss(numc,denc);
%
%  Conversion to discrete transfer function
nstates = size(Ac,1);
invexp = inv(eye(nstates) - (Ts/2)*Ac);
Ad = invexp*(eye(nstates) + (Ts/2)*Ac);
Bd = invexp*Bc;
Cd = Cc*invexp*Ts;
Dd = Cc*invexp*Bc*(Ts/2) + Dc;
%
if Initialize==1  % Compute initial conditions on states
    u1=Vac_Init(1)*exp(j*Vac_Init(2)*pi/180);
    u2=Vdc_Init*exp(j*90*pi/180);
    u=u1+u2;
    u0=imag(u); % input at  t=0;
    I=eye(size(Ac));
    sI1=I*j*(2*pi*Vac_Init(3));
    sI2=I*j*0;
    x=inv(sI1-Ac)*Bc*u1 + inv(sI2-Ac)*Bc*u2;
    x0c=imag(x);
    x0d=(I-Ac*Ts/2)*x0c/Ts - Bc/2*u0;
else
    x0d=0;
end

%
if PlotResponse==1 % Plot frequency and step response
    figure(1)
    sys=ss(Ad,Bd,Cd,Dd,Ts);
    f=param1(1):param1(3):param1(2);
    w=2*pi*f;
    [mag phase]=bode(sys,w);
    subplot(2,1,1)
    plot(f,squeeze(mag))
    title('Magnitude')
    grid
    subplot(2,1,2)
    plot(f,squeeze(phase))
    title('Phase (degrees)')
    xlabel('Hz')
    grid
    figure(2)
    step(sys)
end

