opv=[sv(1),reshape(repmat(sv(1:end-1),2,1),1,2*length(sv)-2),sv(end),sv(end)];

power_initmask();

switch FilterType
case 1, % Lowpass
    X=[0 1 2 3 4];
    Y=[-2 -2 -3 -4 -4];
    numc=1;
    denc=[Tc 1];
case 2,   % Highpass
    X=[0 1 2 3 4];
    Y=[-4 -4 -3 -2 -2];
    numc=[1 0];
    denc=[1 1/Tc];
end
%
[Ac,Bc,Cc,Dc]=tf2ss(numc,denc);
%
%  Conversion to discrete transfer function
nstates = size(Ac,1);
if Ts<=0
    Erreur.message = 'The Sample time parameter must be greater than zero. Note that specifying inherited sample time (-1) does not work for this block';
    Erreur.identifier = 'SpecializedPowerSystems:Discrete1stOrderFilterBlock:ParameterError';
    powericon('psberror',Erreur.message,Erreur.identifier,'NoUiwait');
end
invexp = inv(eye(nstates) - (Ts/2)*Ac);
Ad = invexp*(eye(nstates) + (Ts/2)*Ac);
Bd = invexp*Bc;
Cd = Cc*invexp*Ts;
Dd = Cc*invexp*Bc*(Ts/2) + Dc;
%
if Initialize==1  % Compute initial conditions on states
    u1=Vac_Init(1)*exp(j*Vac_Init(2)*pi/180);
    u2=Vdc_Init*exp(j*90*pi/180);
    u=u1+u2;
    u0=imag(u); % input at  t=0;
    I=eye(size(Ac));
    sI1=I*j*(2*pi*Vac_Init(3));
    sI2=I*j*0;
    x=inv(sI1-Ac)*Bc*u1 + inv(sI2-Ac)*Bc*u2;
    x0c=imag(x);
    x0d=(I-Ac*Ts/2)*x0c/Ts - Bc/2*u0;
else
    x0d=0;
end

%
if PlotResponse==1 % Plot frequency and step response
t=[0:Tc/1000:7*Tc];
f=param1(1):param1(3):param1(2);
w=2*pi*f;
switch FilterType
	case 1, % Lowpass
		Ystep=1 - exp(-t/Tc);
		RepFreq=1./(1+Tc*j.*w);
	case 2,   % Highpass
		Ystep=exp(-t/Tc);
		RepFreq=1./(1 + (1./(Tc*j.*w)));
end
%
Mag=abs(RepFreq);
Pha=angle(RepFreq)*180/pi;
%
figure(1)
subplot(2,1,1)
plot(f,Mag)
grid
title('Bode Diagram')
ylabel('Magnitude')
subplot(2,1,2)
plot(f,Pha)
ylabel('Phase (deg)')
xlabel('Frequency (Hz)')
grid
figure(2)
plot(t,Ystep)
grid
ylabel('Amplitude')
xlabel('Time (s)')
title('Step Response')
end
power_initmask();

%Generator data
Pnom=nom(1)*Nb_wt;
Vnom_gen=nom(2);
Fnom=nom(3);
Xd=Reactances(1);
Xd1=Reactances(2);
Xd2=Reactances(3);
Xq=Reactances(4);
Xq2=Reactances(5);
Xl=Reactances(6);
Tdo1=Time_constants(1);
Tdo2=Time_constants(2);
Tq2=Time_constants(3);
H=mec(1);
F=mec(2);
p=mec(3);

% Converters data
L_RL=RL_grid(1);
R_RL=RL_grid(2);
L_Boost=L_R_Boost(1)/Nb_wt;
R_Boost=L_R_Boost(2)/Nb_wt;
Q_filter=50;
C_DClink=C_DClink1*Nb_wt;
C_var_filter=C_var_filter1*Nb_wt;

% Controller data
Freq_filter=10000;   %Hz
Zeta_filter=0.707;
Kp_dc=Kdc(1);
Ki_dc=Kdc(2);
Kp_grid_side_cur_reg=Kgrid_side_cur_reg(1);
Ki_grid_side_cur_reg=Kgrid_side_cur_reg(2);
Kp_speed=Kspeed(1);
Ki_speed=Kspeed(2);
Kp_boost_cur_reg=Kboost_cur_reg(1);
Ki_boost_cur_reg=Kboost_cur_reg(2);
Kp_compensation=Kcompensation(1);
Ki_compensation=Kcompensation(2);
Kp_field=Kfield(1);
Ki_field=Kfield(2);
Mod_index_max=1.1;
T_speed=5;      %Speed reference time constant (s)
Iq_ref_limit_time_constant=0.3; %(s)
Current_reg_output_limit=1.1;   %(pu)
Var_reg_output_hi_limit=1.1;    %(pu)
Var_reg_output_low_limit=0.9;   %(pu)
Pitch_time_constant=0.01;       %(s)
Vf_limit=10;    %Field voltage limit (pu)
Flux_meas_time_constant=1*(1/Fnom); %(s)
Ts_snub=50e-6;  %Sample time to compute snubber resistance


% Turbine data
Pmec=Pmec1*Nb_wt;
c1 = 0.6450;
c2 = 116;
c3 = .4;
c4 = 5;
c5 = 21;
c6 = .00912;  % Set Pmin in stall condition (does not vary with wind_speed_Pmax)
c7 = .08;
c8 = .035;
theta=0;
CpMax=.5;
lambda_CpMax=9.9495;

c1_c8=[c1 c2 c3 c4 c5 c6 c7 c8];


%   Cp = c1*(c6*lambda + (-c4 - c3*(2.5 + theta) + c2*(1/(lambda + ...
%   c7*(2.5 + theta)) - c8/(1 + (2.5 + theta)^3)))/exp(c5*(1/(lambda + ...
%   c7*(2.5 + theta)) - c8/(1 + (2.5 + theta)^3))))


        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        % Operation at Cp max
        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        rated_omegar=1;
        omegar = rated_omegar;

        % Enforce boundaries on wind speed
        % A warning could be displayed
        if wind_speed_CpMax < 6
            wind_speed_CpMax=6;
            disp('Warning: Wind speed at nominal speed and at Cp max has been set to 6 m/s')
        end
        if wind_speed_CpMax > 30
            wind_speed_CpMax=30;
            disp('Warning: Wind speed at nominal speed and at Cp max has been set to 30 m/s')
        end

        K1=lambda_CpMax/omegar*wind_speed_CpMax;

        % Calculation of K2 needed to get P equal to the requested value at
        % Cp max for the requested wind speed

        Prated=Pmec;
        P_rated_omegar_theta_zero=0.75;

        K2 = P_rated_omegar_theta_zero*Prated/(wind_speed_CpMax^3*CpMax);

        K1_K2=[K1 K2];

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        % End of calculation for operation at Cp max
        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Plot turbine characteristics
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 

DisplayTurbChar=get_param(gcb,'DisplayTurbChar');
if strcmp(DisplayTurbChar,'on')
    vect_theta = 0:2:30;

    vect_lambda = 1:0.2:30;

    clear Cp;

    for i=1:length(vect_theta)
     for j=1:length(vect_lambda)
                Cp(i,j) = c1*(c6*vect_lambda(j) + (-c4 - c3*(2.5 + vect_theta(i)) + c2*(1/(vect_lambda(j) + ...
                c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3)))/exp(c5*(1/(vect_lambda(j) + ...
                c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3))));
     end
    end

    figure(1);
    clf;
    hold on;

    plot(vect_lambda, Cp);
    axis([0, 25, 0, .6]);
    title('Wind Turbine Cp Characteristic (pitch angle increases by step of 2 deg.)');
    ylabel('Cp');
    set(gca,'ytick',[0 .1 .2 .3 .4 .5 .6]);
    xlabel('Lambda');
    grid on;
    text(10.1,0.51,'Pitch angle 0 degree');

    hold off

    % Plot of the wind turbine mechanical power output (pu) lambda and Cp
    % characteristics against wind speed (m/s) for a range of theta.

    wind_speed_range = [1,.2,30];
    vect_wind_speed = 1:0.2:30;

    clear lambda;
    clear Cp;
    clear P;

    for i=1:length(vect_theta)
        for j=1:length(vect_wind_speed)
            lambda(i,j) = K1*omegar/vect_wind_speed(j);
            Cp(i,j) = c1*(c6*lambda(i,j) + (-c4 - c3*(2.5 + vect_theta(i)) + c2*(1/(lambda(i,j) + ...
            c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3)))/exp(c5*(1/(lambda(i,j) + ...
            c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3))));
            P(i,j) = K2/Prated*vect_wind_speed(j)^3*Cp(i,j);
        end
    end


    figure(2);
    clf;
    hold on

    subplot(3,1,1);
    plot(vect_wind_speed, P);
    axis([0, 35, 0, 1.5]);
    title('Wind Turbine Characteristics (w = 1 pu, pitch angle increases by step of 2 deg.)');
    ylabel('P (pu)');
    set(gca,'ytick',0:.5:4);
    grid on;

    subplot(3,1,2);
    plot(vect_wind_speed, lambda);
    axis([0, 35, 0, 20]);
    ylabel('Lambda');
    grid on;

    subplot(3,1,3)
    plot(vect_wind_speed, Cp);
    axis([0, 35, 0, .6]);
    xlabel('Wind Speed (m/s)');
    ylabel('Cp');
    set(gca,'ytick',[0 .1 .2 .3 .4 .5 .6]);
    grid on;

    hold off
    set_param(gcb,'DisplayTurbChar','off')

end

str=sprintf(' Fo=%iHz\n\n',Fo);
Wo=2*pi*Fo;
switch FilterType
case 1, % Lowpass
       X=[0 1 2 3 4];
       Y=[-2 -2 -3 -4 -4];
       n2=0;n1=0;n0=Wo*Wo;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=1;
 case 2,   % Highpass
       X=[0 1 2 3 4];
       Y=[-4 -4 -3 -2 -2];
       n2=1;n1=0;n0=0;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=2;
    case 3,   % Bandpass
       X=[0 1 2 3 4 5 ];
       Y=[-3 -3 -2 -2 -3 -3];
       n2=0;n1=2*Zeta*Wo;n0=0;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=3;
    case 4,  %Bandstop (Notch)
       X=[0 1 2 3 4 5 ];
       Y=[-2 -2 -3 -3 -2 -2];
       n2=1;n1=0;n0=Wo*Wo;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=4;
    end
%
numc=[n2 n1 n0];
denc=[d2 d1 d0];
[Ac,Bc,Cc,Dc]=tf2ss(numc,denc);
%
%  Conversion to discrete transfer function
nstates = size(Ac,1);
invexp = inv(eye(nstates) - (Ts/2)*Ac);
Ad = invexp*(eye(nstates) + (Ts/2)*Ac);
Bd = invexp*Bc;
Cd = Cc*invexp*Ts;
Dd = Cc*invexp*Bc*(Ts/2) + Dc;
%
if Initialize==1  % Compute initial conditions on states
u1=Vac_Init(1)*exp(j*Vac_Init(2)*pi/180);
u2=Vdc_Init*exp(j*90*pi/180);
u=u1+u2;
u0=imag(u); % input at  t=0;
I=eye(size(Ac));
sI1=I*j*(2*pi*Vac_Init(3));
sI2=I*j*0;
x=inv(sI1-Ac)*Bc*u1 + inv(sI2-Ac)*Bc*u2;
x0c=imag(x);
x0d=(I-Ac*Ts/2)*x0c/Ts - Bc/2*u0;
else
x0d=0;
end
%
if PlotResponse==1 % Plot frequency and step response
if Zeta==1
	z=1+1e-12;
else
	z=Zeta;
end
wn=Wo;
t=[0:1/(z*wn)/1000:7/(z*wn)];
f=param1(1):param1(3):param1(2);
w=2*pi*f;
switch FilterType
	case 1, % Lowpass
		Ystep=wn^2*(1/wn^2+1/(4*z^2*wn^2-4*wn^2)^(1/2)*(1/(-z*wn+1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*exp((-z*wn+1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t)-1/(-z*wn-1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*exp((-z*wn-1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t)));
		numFreq=wn^2;
	case 2,   % Highpass
		Ystep=-exp(-z*wn*t)/(z-1)/(z+1).*cos((-wn^2*(z-1)*(z+1))^(1/2)*t)+exp(-z*wn*t)/(z-1)/(z+1)*z^2.*cos((-wn^2*(z-1)*(z+1))^(1/2)*t)+z/wn*exp(-z*wn*t)/(z-1)/(z+1)*(wn^2-z^2*wn^2)^(1/2).*sin((-wn^2*(z-1)*(z+1))^(1/2)*t);
		numFreq=-w.^2;
	case 3,   % Bandpass
		Ystep=2*z*wn/(4*z^2*wn^2-4*wn^2)^(1/2)*(exp((-z*wn+1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t)-exp((-z*wn-1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t));
		numFreq=2*Zeta*wn.*w*j;
	case 4,  %Bandstop (Notch)
		Ystep=1+2*z/wn*exp(-z*wn*t)/(z-1)/(z+1)*(wn^2-z^2*wn^2)^(1/2).*sin((-wn^2*(z-1)*(z+1))^(1/2)*t);	
		numFreq=wn^2-w.^2;
end
%
denFreq=(wn^2-w.^2) + 2*Zeta*wn*j.*w;
RepFreq=numFreq./denFreq;
Mag=abs(RepFreq);
Pha=angle(RepFreq)*180/pi;
%
figure(1)
subplot(2,1,1)
plot(f,Mag)
grid
title('Bode Diagram')
ylabel('Magnitude')
subplot(2,1,2)
plot(f,Pha)
ylabel('Phase (deg)')
xlabel('Frequency (Hz)')
grid
figure(2)
plot(t,real(Ystep))
grid
ylabel('Amplitude')
xlabel('Time (s)')
title('Step Response')
end
