    subplot(2,1,1)
    plot(f,squeeze(mag))
    title('Magnitude')
    grid
    subplot(2,1,2)
    plot(f,squeeze(phase))
    title('Phase (degrees)')
    xlabel('Hz')
    grid
    figure(2)
    step(sys)
end

