%Generator data
Pnom=nom(1)*Nb_wt;
Vnom_gen=nom(2);
Fnom=nom(3);
Xd=Reactances(1);
Xd1=Reactances(2);
Xd2=Reactances(3);
Xq=Reactances(4);
Xq2=Reactances(5);
