str=sprintf(' Fo=%iHz\n\n',Fo);
Wo=2*pi*Fo;
switch FilterType
case 1, % Lowpass
       X=[0 1 2 3 4];
       Y=[-2 -2 -3 -4 -4];
       n2=0;n1=0;n0=Wo*Wo;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=1;
 case 2,   % Highpass
       X=[0 1 2 3 4];
       Y=[-4 -4 -3 -2 -2];
       n2=1;n1=0;n0=0;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=2;
    case 3,   % Bandpass
       X=[0 1 2 3 4 5 ];
       Y=[-3 -3 -2 -2 -3 -3];
       n2=0;n1=2*Zeta*Wo;n0=0;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=3;
    case 4,  %Bandstop (Notch)
       X=[0 1 2 3 4 5 ];
       Y=[-2 -2 -3 -3 -2 -2];
       n2=1;n1=0;n0=Wo*Wo;
       d2=1;d1=2*Zeta*Wo;d0=Wo*Wo;
	   Ystep=4;
    end
%
numc=[n2 n1 n0];
denc=[d2 d1 d0];
[Ac,Bc,Cc,Dc]=tf2ss(numc,denc);
%
%  Conversion to discrete transfer function
nstates = size(Ac,1);
invexp = inv(eye(nstates) - (Ts/2)*Ac);
Ad = invexp*(eye(nstates) + (Ts/2)*Ac);
Bd = invexp*Bc;
Cd = Cc*invexp*Ts;
Dd = Cc*invexp*Bc*(Ts/2) + Dc;
%
if Initialize==1  % Compute initial conditions on states
u1=Vac_Init(1)*exp(j*Vac_Init(2)*pi/180);
u2=Vdc_Init*exp(j*90*pi/180);
u=u1+u2;
u0=imag(u); % input at  t=0;
I=eye(size(Ac));
sI1=I*j*(2*pi*Vac_Init(3));
sI2=I*j*0;
x=inv(sI1-Ac)*Bc*u1 + inv(sI2-Ac)*Bc*u2;
x0c=imag(x);
x0d=(I-Ac*Ts/2)*x0c/Ts - Bc/2*u0;
else
x0d=0;
end
%
if PlotResponse==1 % Plot frequency and step response
if Zeta==1
	z=1+1e-12;
else
	z=Zeta;
end
wn=Wo;
t=[0:1/(z*wn)/1000:7/(z*wn)];
f=param1(1):param1(3):param1(2);
w=2*pi*f;
switch FilterType
	case 1, % Lowpass
		Ystep=wn^2*(1/wn^2+1/(4*z^2*wn^2-4*wn^2)^(1/2)*(1/(-z*wn+1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*exp((-z*wn+1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t)-1/(-z*wn-1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*exp((-z*wn-1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t)));
		numFreq=wn^2;
	case 2,   % Highpass
		Ystep=-exp(-z*wn*t)/(z-1)/(z+1).*cos((-wn^2*(z-1)*(z+1))^(1/2)*t)+exp(-z*wn*t)/(z-1)/(z+1)*z^2.*cos((-wn^2*(z-1)*(z+1))^(1/2)*t)+z/wn*exp(-z*wn*t)/(z-1)/(z+1)*(wn^2-z^2*wn^2)^(1/2).*sin((-wn^2*(z-1)*(z+1))^(1/2)*t);
		numFreq=-w.^2;
	case 3,   % Bandpass
		Ystep=2*z*wn/(4*z^2*wn^2-4*wn^2)^(1/2)*(exp((-z*wn+1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t)-exp((-z*wn-1/2*(4*z^2*wn^2-4*wn^2)^(1/2))*t));
		numFreq=2*Zeta*wn.*w*j;
	case 4,  %Bandstop (Notch)
		Ystep=1+2*z/wn*exp(-z*wn*t)/(z-1)/(z+1)*(wn^2-z^2*wn^2)^(1/2).*sin((-wn^2*(z-1)*(z+1))^(1/2)*t);	
		numFreq=wn^2-w.^2;
end
%
denFreq=(wn^2-w.^2) + 2*Zeta*wn*j.*w;
RepFreq=numFreq./denFreq;
Mag=abs(RepFreq);
Pha=angle(RepFreq)*180/pi;
%
figure(1)
subplot(2,1,1)
plot(f,Mag)
grid
title('Bode Diagram')
ylabel('Magnitude')
subplot(2,1,2)
plot(f,Pha)
ylabel('Phase (deg)')
xlabel('Frequency (Hz)')
grid
figure(2)
plot(t,real(Ystep))
grid
ylabel('Amplitude')
xlabel('Time (s)')
title('Step Response')
end
