c1 = 0.6450;
c2 = 116;
c3 = .4;
c4 = 5;
c5 = 21;
c6 = .00912;  % Set Pmin in stall condition (does not vary with wind_speed_Pmax)
c7 = .08;
c8 = .035;
theta=0;
CpMax=.5;
lambda_CpMax=9.9495;

c1_c8=[c1 c2 c3 c4 c5 c6 c7 c8];


%   Cp = c1*(c6*lambda + (-c4 - c3*(2.5 + theta) + c2*(1/(lambda + ...
%   c7*(2.5 + theta)) - c8/(1 + (2.5 + theta)^3)))/exp(c5*(1/(lambda + ...
%   c7*(2.5 + theta)) - c8/(1 + (2.5 + theta)^3))))


        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
