        end
        if wind_speed_CpMax > 30
            wind_speed_CpMax=30;
            disp('Warning: Wind speed at nominal speed and at Cp max has been set to 30 m/s')
        end

        K1=lambda_CpMax/omegar*wind_speed_CpMax;

        % Calculation of K2 needed to get P equal to the requested value at
        % Cp max for the requested wind speed

        Prated=Pmec;
        P_rated_omegar_theta_zero=0.75;

        K2 = P_rated_omegar_theta_zero*Prated/(wind_speed_CpMax^3*CpMax);

