DisplayTurbChar=get_param(gcb,'DisplayTurbChar');
if strcmp(DisplayTurbChar,'on')
    vect_theta = 0:2:30;

    vect_lambda = 1:0.2:30;

    clear Cp;

    for i=1:length(vect_theta)
     for j=1:length(vect_lambda)
                Cp(i,j) = c1*(c6*vect_lambda(j) + (-c4 - c3*(2.5 + vect_theta(i)) + c2*(1/(vect_lambda(j) + ...
                c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3)))/exp(c5*(1/(vect_lambda(j) + ...
                c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3))));
     end
    end

    figure(1);
    clf;
    hold on;

    plot(vect_lambda, Cp);
    axis([0, 25, 0, .6]);
    title('Wind Turbine Cp Characteristic (pitch angle increases by step of 2 deg.)');
    ylabel('Cp');
    set(gca,'ytick',[0 .1 .2 .3 .4 .5 .6]);
    xlabel('Lambda');
    grid on;
    text(10.1,0.51,'Pitch angle 0 degree');

    hold off

    % Plot of the wind turbine mechanical power output (pu) lambda and Cp
    % characteristics against wind speed (m/s) for a range of theta.

    wind_speed_range = [1,.2,30];
    vect_wind_speed = 1:0.2:30;

    clear lambda;
    clear Cp;
    clear P;

    for i=1:length(vect_theta)
        for j=1:length(vect_wind_speed)
            lambda(i,j) = K1*omegar/vect_wind_speed(j);
            Cp(i,j) = c1*(c6*lambda(i,j) + (-c4 - c3*(2.5 + vect_theta(i)) + c2*(1/(lambda(i,j) + ...
            c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3)))/exp(c5*(1/(lambda(i,j) + ...
            c7*(2.5 + vect_theta(i))) - c8/(1 + (2.5 + vect_theta(i))^3))));
            P(i,j) = K2/Prated*vect_wind_speed(j)^3*Cp(i,j);
        end
    end


    figure(2);
    clf;
    hold on

    subplot(3,1,1);
    plot(vect_wind_speed, P);
    axis([0, 35, 0, 1.5]);
    title('Wind Turbine Characteristics (w = 1 pu, pitch angle increases by step of 2 deg.)');
    ylabel('P (pu)');
    set(gca,'ytick',0:.5:4);
    grid on;

    subplot(3,1,2);
    plot(vect_wind_speed, lambda);
    axis([0, 35, 0, 20]);
    ylabel('Lambda');
    grid on;

    subplot(3,1,3)
    plot(vect_wind_speed, Cp);
    axis([0, 35, 0, .6]);
    xlabel('Wind Speed (m/s)');
    ylabel('Cp');
    set(gca,'ytick',[0 .1 .2 .3 .4 .5 .6]);
    grid on;

    hold off
    set_param(gcb,'DisplayTurbChar','off')

end

